40	/**
41	 * Represents a validated and ready-to-execute tool call.
42	 * An instance of this is created by a `ToolBuilder`.
43	 */
44	export interface ToolInvocation<
45	  TParams extends object,
46	  TResult extends ToolResult,
47	> {
48	  /**
49	   * The validated parameters for this specific invocation.
50	   */
51	  params: TParams;
