53	  /**
54	   * Gets a pre-execution description of the tool operation.
55	   *
56	   * @returns A markdown string describing what the tool will do.
57	   */
58	  getDescription(): string;
59	
60	  /**
61	   * Determines what file system paths the tool will affect.
62	   * @returns A list of such paths.
63	   */
64	  toolLocations(): ToolLocation[];
65	
66	  /**
67	   * Checks if the tool call should be confirmed by the user before execution.
68	   *
69	   * @param abortSignal An AbortSignal that can be used to cancel the confirmation request.
70	   * @returns A ToolCallConfirmationDetails object if confirmation is required, or false if not.
71	   */
72	  shouldConfirmExecute(
73	    abortSignal: AbortSignal,
74	    forcedDecision?: ForcedToolDecision,
75	  ): Promise<ToolCallConfirmationDetails | false>;
76	
77	  /**
78	   * Executes the tool with the validated parameters.
79	   * @param signal AbortSignal for tool cancellation.
80	   * @param updateOutput Optional callback to stream output.
81	   * @param setExecutionIdCallback Optional callback for tools that expose a background execution handle.
82	   * @returns Result of the tool execution.
83	   */
84	  execute(
85	    signal: AbortSignal,
86	    updateOutput?: (output: ToolLiveOutput) => void,
87	    options?: ExecuteOptions,
88	  ): Promise<TResult>;
89	
90	  /**
91	   * Returns tool-specific options for policy updates.
92	   * This is used by the scheduler to narrow policy rules when a tool is approved.
93	   */
94	  getPolicyUpdateOptions?(
95	    outcome: ToolConfirmationOutcome,
96	  ): PolicyUpdateOptions | undefined;
97	}
