99	/**
100	 * Structured payload used by tools to surface background execution metadata to
101	 * the CLI UI.
102	 *
103	 * NOTE: `pid` is used as the canonical identifier for now to stay consistent
104	 * with existing types (ExecutingToolCall.pid, ExecutionHandle.pid, etc.).
105	 * A future rename to `executionId` is planned once the codebase is fully
106	 * migrated — not done in this PR to keep the diff focused on the abstraction.
107	 */
108	export interface BackgroundExecutionData extends Record<string, unknown> {
109	  pid?: number;
110	  command?: string;
111	  initialOutput?: string;
112	}
113	
114	export function isBackgroundExecutionData(
115	  data: unknown,
116	): data is BackgroundExecutionData {
117	  if (typeof data !== 'object' || data === null) {
118	    return false;
119	  }
120	
121	  const pid = 'pid' in data ? data.pid : undefined;
122	  const command = 'command' in data ? data.command : undefined;
123	  const initialOutput =
124	    'initialOutput' in data ? data.initialOutput : undefined;
125	
126	  return (
127	    (pid === undefined || typeof pid === 'number') &&
128	    (command === undefined || typeof command === 'string') &&
129	    (initialOutput === undefined || typeof initialOutput === 'string')
130	  );
131	}
