152	    readonly params: TParams,
153	    protected readonly messageBus: MessageBus,
154	    readonly _toolName?: string,
155	    readonly _toolDisplayName?: string,
156	    readonly _serverName?: string,
157	    readonly _toolAnnotations?: Record<string, unknown>,
158	    readonly respectsAutoEdit: boolean = false,
159	    readonly getApprovalMode: () => ApprovalMode = () => ApprovalMode.DEFAULT,
160	  ) {}
161	
162	  abstract getDescription(): string;
163	
164	  toolLocations(): ToolLocation[] {
165	    return [];
166	  }
167	
168	  async shouldConfirmExecute(
169	    abortSignal: AbortSignal,
170	    forcedDecision?: ForcedToolDecision,
171	  ): Promise<ToolCallConfirmationDetails | false> {
172	    if (
173	      this.respectsAutoEdit &&
174	      this.getApprovalMode() === ApprovalMode.AUTO_EDIT &&
175	      forcedDecision !== 'ask_user'
176	    ) {
177	      return false;
178	    }
179	
180	    const decision =
181	      forcedDecision ?? (await this.getMessageBusDecision(abortSignal));
182	    if (decision === 'allow') {
183	      return false;
184	    }
185	
186	    if (decision === 'deny') {
187	      throw new Error(
188	        `Tool execution for "${
189	          this._toolDisplayName || this._toolName
190	        }" denied by policy.`,
191	      );
192	    }
193	
194	    if (decision === 'ask_user') {
195	      return this.getConfirmationDetails(abortSignal);
196	    }
197	
198	    // Default to confirmation details if decision is unknown (should not happen with exhaustive policy)
199	    return this.getConfirmationDetails(abortSignal);
200	  }
